textkit/counts.py.new:
"""Count each token, keeping insertion order."""
counts: dict[str, int] = {}
for token in tokens:
    counts[token] = counts.get(token, 0) + 1
return counts

textkit/report.py.new:
"""Return total, unique and top-word fields for a summary report."""
return {
    "total_words": sum(counts.values()),
    "unique_words": len(counts),
    "top": list(top),
}

